package com.lucid.os.updater;
import android.app.*;import android.content.*;import android.os.*;import androidx.core.app.NotificationCompat;import java.io.*;import java.net.*;import java.security.*;import java.util.*;
public final class DownloadService extends Service{
 public static final String ACTION="com.lucid.os.updater.PROGRESS",URL="url",SHA="sha256",VERSION="version";static final String CHANNEL="lucid_download";static final int ID=4201;PowerManager.WakeLock lock;private volatile boolean downloading=false;
 public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL,"Update downloads",NotificationManager.IMPORTANCE_LOW));}
 public int onStartCommand(Intent i,int f,int id){try{startForeground(ID,note("Connecting to update server…",0,false).build());}catch(Throwable e){broadcast("Download failed: foreground service startup error ("+e.getClass().getSimpleName()+"): "+String.valueOf(e.getMessage()),0,false,false,0,0);stopSelf();return START_NOT_STICKY;}if(i==null){broadcast("Download failed: service received no download request.",0,false,false,0,0);stopSelf(id);return START_NOT_STICKY;}if(downloading){broadcast("Download already in progress",-1,false,false,0,0);return START_NOT_STICKY;}downloading=true;broadcast("Download service running — connecting to release server…",-1,false,false,0,0);new Thread(()->run(i.getStringExtra(URL),i.getStringExtra(SHA),i.getStringExtra(VERSION),id),"LucidUpdaterDownload").start();return START_REDELIVER_INTENT;}
 void run(String url,String sha,String ver,int id){File part=new File(getFilesDir(),"lucidos-update.zip.part"),out=new File(getFilesDir(),"lucidos-update.zip");HttpURLConnection c=null;try{PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);lock=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"LucidUpdater:download");lock.acquire(4*60*60*1000L);if(url==null||!url.startsWith("https://")||sha==null||!sha.matches("(?i)[0-9a-f]{64}")||sha.matches("0{64}"))throw new Exception("Invalid URL/checksum");c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(60000);if(c.getResponseCode()!=200)throw new Exception("HTTP "+c.getResponseCode());long total=c.getContentLengthLong(),done=0,last=0;MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new BufferedInputStream(c.getInputStream());FileOutputStream os=new FileOutputStream(part)){byte[] b=new byte[131072];int n;while((n=in.read(b))!=-1){os.write(b,0,n);d.update(b,0,n);done+=n;long now=System.currentTimeMillis();if(now-last>350){int pct=total>0?(int)Math.min(99,done*100/total):-1;String msg=human(done)+(total>0?" / "+human(total):"");broadcast(msg,pct,total>0,false,done,total);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,note(msg,pct,total>0).build());last=now;}}os.getFD().sync();}StringBuilder h=new StringBuilder();for(byte b:d.digest())h.append(String.format(Locale.ROOT,"%02x",b&255));if(!h.toString().equalsIgnoreCase(sha))throw new Exception("SHA-256 mismatch");if(!part.renameTo(out)){try(InputStream in=new FileInputStream(part);OutputStream os=new FileOutputStream(out)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)os.write(b,0,n);}part.delete();}getSharedPreferences("updater",0).edit().putBoolean("download_verified",true).putString("download_sha256",h.toString()).putString("download_version",ver==null?"":ver).apply();broadcast("Download complete — SHA-256 verified",100,true,true,out.length(),out.length());((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,note("Download verified — ready to install",100,true).setOngoing(false).build());}catch(Exception e){part.delete();getSharedPreferences("updater",0).edit().putBoolean("download_verified",false).apply();broadcast("Download failed: "+e.getMessage(),0,false,false,0,0);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,note("Download failed: "+e.getMessage(),0,false).setOngoing(false).build());}finally{if(c!=null)c.disconnect();if(lock!=null&&lock.isHeld())lock.release();downloading=false;stopForeground(true);stopSelf(id);}}
 void broadcast(String msg,int pct,boolean determinate,boolean done,long bytes,long total){getSharedPreferences("updater",0).edit().putString("download_status",msg).putInt("download_status_progress",pct).putBoolean("download_status_determinate",determinate).putBoolean("download_status_done",done).putLong("download_status_bytes",bytes).putLong("download_status_total",total).putLong("download_status_time",System.currentTimeMillis()).apply();Intent i=new Intent(ACTION).setPackage(getPackageName()).putExtra("message",msg).putExtra("progress",pct).putExtra("determinate",determinate).putExtra("done",done).putExtra("bytes",bytes).putExtra("total",total);sendBroadcast(i);}
 NotificationCompat.Builder note(String s,int p,boolean determinate){PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationCompat.Builder b=new NotificationCompat.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle("Lucid System Updater").setContentText(s).setContentIntent(pi).setOnlyAlertOnce(true).setOngoing(true).setPriority(NotificationCompat.PRIORITY_LOW);if(determinate)b.setProgress(100,Math.max(0,Math.min(100,p)),false);else b.setProgress(0,0,true);return b;}
 String human(long n){if(n<1048576)return String.format(Locale.ROOT,"%.0f KB",n/1024.0);if(n<1073741824L)return String.format(Locale.ROOT,"%.1f MB",n/1048576.0);return String.format(Locale.ROOT,"%.2f GB",n/1073741824.0);}public IBinder onBind(Intent i){return null;}
}